"""Read-only M0 contract review. This module grants no execution authority."""

import json
from pathlib import Path

from jsonschema import Draft202012Validator
from jsonschema.exceptions import SchemaError


# Freeze the existing research baseline while engineering milestones are reviewed.
EXPECTED_STATE = {
    "baseline_generation": "GEN-6.11-PASSIVE-EXECUTION-001",
    "current_certified_phase": "6.11",
    "final_holdout_status": "LOCKED/UNTOUCHED",
    "final_holdout_access_count": 0,
    "live_trading_status": "BLOCKED",
    "allow_live_trading": False,
    "lifetime_formal_hypotheses": 20,
    "validated_development_edge": 0,
    "research_validation_status": "PASSIVE_EXECUTION_UNVIABLE (edge=0, camino_b_concluded)",
}


def validate_m0_state(state):
    """Return violations without changing PROJECT_STATE or runtime settings."""
    if not isinstance(state, dict):
        return ["M0_STATE_INVALID: expected an object"]
    errors = []
    for key, expected in EXPECTED_STATE.items():
        observed = state.get(key)
        if type(observed) is not type(expected) or observed != expected:
            errors.append(f"M0_STATE_MISMATCH: {key}")
    # These counters are not recorded by the current PROJECT_STATE. If a later
    # state records them, they must be zero. Absence is disclosed in the review.
    for key in ("holdout_bars_read", "holdout_bytes_read", "final_holdout_bars_read", "final_holdout_bytes_read"):
        if key in state and (type(state[key]) is not int or state[key] != 0):
            errors.append(f"M0_STATE_MISMATCH: {key}")
    return errors


def review_m0(project_root):
    """Review fixed metadata paths only; never load dataset/holdout contents."""
    root = Path(project_root) / "quantumbot_harness"
    sources = {
        "contract": root / "policies" / "V2_INVARIANTS.json",
        "schema": root / "schemas" / "v2_invariants_manifest.schema.json",
        "design": root / "specs" / "SPEC-HARNESS-V2-ENGINEERING-001.json",
        "state": root / "PROJECT_STATE.json",
    }
    documents, errors = {}, []
    for name, path in sources.items():
        try:
            documents[name] = json.loads(path.read_text(encoding="utf-8"))
            if not isinstance(documents[name], dict):
                errors.append(f"M0_DOCUMENT_INVALID: {name}")
        except (OSError, ValueError) as exc:
            errors.append(f"M0_SOURCE_UNAVAILABLE: {name} ({type(exc).__name__})")

    if not errors:
        try:
            Draft202012Validator.check_schema(documents["schema"])
            for error in Draft202012Validator(documents["schema"]).iter_errors(documents["contract"]):
                errors.append(f"M0_CONTRACT_INVALID: {error.json_path}: {error.message}")
        except SchemaError as exc:
            errors.append(f"M0_SCHEMA_INVALID: {exc}")

        if documents["contract"].get("invariants") != documents["design"].get("inherited_immutable_invariants"):
            errors.append("M0_INHERITANCE_MISMATCH")
        errors.extend(validate_m0_state(documents["state"]))

    state = documents.get("state", {})
    if not isinstance(state, dict):
        state = {}
    return {
        "review_id": "HARNESS-V2-M0-REVIEW-001",
        "status": "BLOCKED" if errors else "PASS",
        "milestone_status": "BLOCKED" if errors else "READY_FOR_INDEPENDENT_REVIEW",
        "certification_effect": "NONE",
        "errors": errors,
        "observed_state": {key: state.get(key) for key in EXPECTED_STATE},
        "unrecorded_counters": [
            label for label, aliases in (
                ("holdout_bars_read", ("holdout_bars_read", "final_holdout_bars_read")),
                ("holdout_bytes_read", ("holdout_bytes_read", "final_holdout_bytes_read")),
            ) if not any(key in state for key in aliases)
        ],
        "limits": [
            "Review checks metadata and contracts; it does not certify M0 or authorize M1.",
            "Absent bar/byte counters are not evidence of measured zero reads.",
            "Historical artifact immutability is checked by baseline hashes and the existing gate verifier, not by a new filesystem write interceptor.",
        ],
    }

"""Additive, read-only M0 entry point; historical harness bytes stay sealed.

This is not a global filesystem sandbox or a certification authority. Only
callers using this entry point receive the additional safety checks.
"""

import argparse
import copy
import hashlib
import importlib.util
import ntpath
from pathlib import Path
from types import FunctionType

from quantumbot_harness.core.m0_invariants import validate_m0_state


PROJECT_ROOT = Path(__file__).resolve().parents[2]
HISTORICAL_HARNESS_SHA256 = "b6eefcba50ed0bc520c25dc048a1f1ffd5358dc975d82e64af65036a3ed7bd27"


def _path_forms(value):
    raw = str(value).replace("\\", "/").casefold()
    # Win32 ignores trailing dots/spaces in ordinary path components.
    windows = "/".join(part.rstrip(" .") for part in raw.split("/"))
    return (raw, windows, ntpath.normpath(windows).replace("\\", "/"))


def protected_path(value, patterns, project_root=PROJECT_ROOT):
    """Check both spelling and resolved aliases, without opening file contents."""
    forms = list(_path_forms(value))
    resolved = (Path(project_root) / str(value).replace("\\", "/")).resolve()
    forms.extend(_path_forms(resolved))
    return any(
        str(pattern).replace("\\", "/").casefold().strip("/") in form
        for pattern in patterns
        for form in forms
    )


def load_safe_harness(project_root=PROJECT_ROOT):
    """Load an isolated legacy module; never patch the shared imported harness."""
    root = Path(project_root).resolve()
    source_path = root / "harness.py"
    source_bytes = source_path.read_bytes()
    if hashlib.sha256(source_bytes).hexdigest() != HISTORICAL_HARNESS_SHA256:
        raise RuntimeError("SAFETY_HARNESS_SOURCE_DRIFT")
    # The historical module ensures these directories on import. Require them
    # to exist so this read-only entry does not bootstrap a missing project.
    for directory in ("candidates", "executions"):
        if not (root / "quantumbot_harness" / directory).is_dir():
            raise RuntimeError("SAFETY_HARNESS_METADATA_MISSING")
    spec = importlib.util.spec_from_file_location(
        "_quantumbot_m0_safe_harness", root / "harness.py"
    )
    if spec is None or spec.loader is None:
        raise RuntimeError("SAFETY_HARNESS_UNAVAILABLE")
    legacy = importlib.util.module_from_spec(spec)
    # Execute the exact verified bytes, not a second read of potentially changed
    # source or a cached bytecode file.
    exec(compile(source_bytes, str(source_path), "exec"), legacy.__dict__)

    legacy.is_protected_path = lambda value: protected_path(
        value, legacy.PROTECTED_PATTERNS, root
    )
    original_validate = legacy.cmd_validate
    original_gate = legacy.cmd_gate
    original_hash = legacy.compute_file_sha256
    original_load = legacy.load_json

    def assert_safe_read(path):
        if protected_path(path, ("FINAL_HOLDOUT", ".env", "quantumbot.db"), root):
            raise PermissionError("BLOCKED_PROTECTED_PATH: forbidden file read")
        resolved = (root / path).resolve()
        if not resolved.is_relative_to(root):
            raise PermissionError("BLOCKED_OUTSIDE_PROJECT: forbidden file read")
        return resolved

    def load_metadata(path):
        return original_load(assert_safe_read(path))

    def validate(args):
        try:
            state = legacy.load_json(legacy.HARNESS_DIR / "PROJECT_STATE.json")
        except (OSError, ValueError) as exc:
            print(f"BLOCKED_SAFETY_STATE: {type(exc).__name__}")
            return 1
        errors = validate_m0_state(state)
        if errors:
            for error in errors:
                print(f"BLOCKED_SAFETY_STATE: {error}")
            return 1
        print("[SAFETY PASS] Phase 6.11 metadata: holdout locked, recorded accesses 0, LIVE blocked.")
        print("[SAFETY LIMIT] Missing bar/byte counters are not measured zero reads.")
        return original_validate(args)

    def fingerprint_file(path):
        # A second check at the actual read boundary also covers gate receipts.
        # Sealed engine source hashes remain readable for historical verification.
        return original_hash(assert_safe_read(path))

    def gate(args):
        # Preflight every required receipt before delegating any source hashing.
        # The historical verifier checks hashes but does not enforce VERIFIED.
        try:
            document = copy.deepcopy(legacy.load_json(legacy.GATES_DIR / f"{args.gate_id}.json"))
            index = copy.deepcopy(legacy.load_json(legacy.RECEIPTS_DIR / "index.json"))
        except (OSError, ValueError) as exc:
            print(f"BLOCKED_RECEIPT_METADATA: {type(exc).__name__}")
            return 1
        required = document.get("required_receipts") if isinstance(document, dict) else None
        receipts = index.get("receipts") if isinstance(index, dict) else None
        if (
            not isinstance(required, list)
            or any(not isinstance(value, str) or not value for value in required)
            or len(set(required)) != len(required)
            or not isinstance(receipts, list)
            or any(not isinstance(receipt, dict) for receipt in receipts)
        ):
            print("BLOCKED_RECEIPT_METADATA: invalid receipt requirements/index")
            return 1
        for receipt_id in required:
            matches = [receipt for receipt in receipts if receipt.get("receipt_id") == receipt_id]
            if len(matches) != 1:
                print(f"BLOCKED_REQUIRED_RECEIPT: {receipt_id}: MISSING_OR_AMBIGUOUS")
                return 1
            if matches[0].get("verification_status") != "VERIFIED":
                print(f"BLOCKED_REQUIRED_RECEIPT: {receipt_id}: NOT_VERIFIED")
                return 1
        def checked_metadata(path):
            if Path(path) == legacy.RECEIPTS_DIR / "index.json":
                return index
            if Path(path) == legacy.GATES_DIR / f"{args.gate_id}.json":
                return document
            return legacy.load_json(path)

        # Evaluate the same checked gate/index snapshots. A second metadata
        # read must not replace a VERIFIED receipt after the preflight.
        evaluate = FunctionType(
            original_gate.__code__,
            {**original_gate.__globals__, "load_json": checked_metadata},
            original_gate.__name__, original_gate.__defaults__, original_gate.__closure__,
        )
        return evaluate(args)

    legacy.load_json = load_metadata
    legacy.cmd_validate = validate
    legacy.cmd_gate = gate
    legacy.compute_file_sha256 = fingerprint_file
    return legacy


def main(argv=None):
    parser = argparse.ArgumentParser(
        description="M0 safe read-only commands; no certification or trading authority."
    )
    subparsers = parser.add_subparsers(dest="command", required=True)
    subparsers.add_parser("validate")
    fingerprint = subparsers.add_parser("fingerprint")
    fingerprint.add_argument("paths", nargs="+")
    verify = subparsers.add_parser("verify-all")
    verify.add_argument("gate_id")
    args = parser.parse_args(argv)
    # Gate IDs are identifiers, not arbitrary filesystem paths.
    if args.command == "verify-all" and (
        not args.gate_id.startswith("GATE-")
        or not all(char.isalnum() or char in "-_." for char in args.gate_id)
        or ".." in args.gate_id
    ):
        print("BLOCKED_INVALID_GATE_ID")
        return 2
    try:
        legacy = load_safe_harness()
        # Every command checks state before file hashing or legacy verification.
        if args.command == "validate":
            return legacy.cmd_validate(args)
        state = legacy.load_json(legacy.HARNESS_DIR / "PROJECT_STATE.json")
        errors = validate_m0_state(state)
        if errors:
            for error in errors:
                print(f"BLOCKED_SAFETY_STATE: {error}")
            return 1
        if args.command == "fingerprint":
            return legacy.cmd_fingerprint(args)
        return legacy.cmd_verify_all(args)
    except (OSError, ValueError, RuntimeError) as exc:
        print(f"BLOCKED_SAFETY_COMMAND: {type(exc).__name__}: {exc}")
        return 2

"""Read-only verifier for the approved M0 registry.

It can establish registry integrity and a blocked/ready disposition. It cannot
certify M0, create receipts, mutate ledgers, authorize LIVE, or promote M1.
"""

import hashlib
import json
from pathlib import Path

from quantumbot_harness.core.m0_invariants import validate_m0_state
from quantumbot_harness.core.safety_cli import protected_path


EXPECTED_REGISTRY_ID = "HARNESS-M0-REGISTRY-001"
EXPECTED_STATUS = "READY_FOR_INDEPENDENT_REVIEW"
EXPECTED_FORMAL_GATE_STATUS = "BLOCKED"
EXPECTED_BASELINE = "GEN-6.11-PASSIVE-EXECUTION-001"
REQUIRED_BOUND_SOURCES = frozenset({
    "quantumbot_harness/core/safety_cli.py",
    "scripts/run_harness_v2_safe.py",
    "tests/test_harness_m0_safety_cli.py",
    "tests/test_m0_formalization_draft.py",
    "quantumbot_harness/specs/SPEC-HARNESS-M0-FORMALIZATION-001.json",
    "quantumbot_harness/docs/M0_FORMALIZATION_PLAN.md",
    "quantumbot_harness/docs/M0_RECEIPT_STATUS_CORRECTION.md",
    "harness.py",
})
REQUIRED_RECEIPTS = (
    "RECEIPT-M0-AUTHORIZATION-001",
    "RECEIPT-M0-CONTROLS-001",
    "RECEIPT-M0-INVARIANTS-001",
    "RECEIPT-M0-PRESERVATION-001",
    "RECEIPT-M0-INDEPENDENT-AUDIT-001",
)


def _load(path):
    return json.loads(Path(path).read_text(encoding="utf-8"))


def _hash(path):
    digest = hashlib.sha256()
    with Path(path).open("rb") as source:
        for chunk in iter(lambda: source.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _safe_source(root, relative):
    if not isinstance(relative, str) or not relative or Path(relative).is_absolute():
        raise PermissionError("SOURCE_PATH_INVALID")
    if ".." in Path(relative).parts:
        raise PermissionError("SOURCE_PATH_INVALID")
    if protected_path(relative, ("FINAL_HOLDOUT", ".env", "quantumbot.db"), root):
        raise PermissionError("SOURCE_PATH_PROTECTED")
    resolved = (root / relative).resolve()
    if not resolved.is_relative_to(root):
        raise PermissionError("SOURCE_PATH_OUTSIDE_PROJECT")
    return resolved


def verify_registry(project_root):
    root = Path(project_root).resolve()
    errors = []
    try:
        registry_path = _safe_source(root, "quantumbot_harness/milestones/M0/REGISTRY.json")
        registry = _load(registry_path)
    except (OSError, PermissionError, ValueError) as exc:
        return {"status": "BLOCKED", "certification_effect": "NONE", "errors": [f"REGISTRY_UNAVAILABLE:{type(exc).__name__}"]}

    if not isinstance(registry, dict):
        return {"status": "BLOCKED", "certification_effect": "NONE", "errors": ["REGISTRY_SHAPE_INVALID"]}

    if registry.get("registry_id") != EXPECTED_REGISTRY_ID:
        errors.append("REGISTRY_ID_MISMATCH")
    if registry.get("status") != EXPECTED_STATUS:
        errors.append("REGISTRY_STATUS_NOT_REVIEW_READY")
    if registry.get("formal_gate_status") != EXPECTED_FORMAL_GATE_STATUS:
        errors.append("REGISTRY_MUST_REMAIN_BLOCKED")
    if registry.get("certification_effect") != "NONE":
        errors.append("REGISTRY_CANNOT_CERTIFY")
    if registry.get("next_action") != "EXTERNAL_REVIEW":
        errors.append("REGISTRY_NEXT_ACTION_INVALID")
    if registry.get("m1_authorized") is not False or registry.get("live_trading_allowed") is not False:
        errors.append("REGISTRY_AUTHORITY_ESCALATION")
    if registry.get("final_holdout_accessed") is not False:
        errors.append("REGISTRY_HOLDOUT_ASSERTION_INVALID")
    if registry.get("spec_id") != "SPEC-HARNESS-M0-FORMALIZATION-001":
        errors.append("REGISTRY_SPEC_ID_MISMATCH")
    if registry.get("baseline_generation") != EXPECTED_BASELINE:
        errors.append("REGISTRY_BASELINE_MISMATCH")
    if registry.get("inherited_invariants_source") != "quantumbot_harness/policies/V2_INVARIANTS.json":
        errors.append("REGISTRY_INVARIANTS_SOURCE_MISMATCH")
    approval = registry.get("approved_scope")
    if not isinstance(approval, dict) or not approval.get("approved_by") or not approval.get("approved_at"):
        errors.append("REGISTRY_APPROVAL_METADATA_INVALID")
    required_receipts = registry.get("required_receipts")
    if not isinstance(required_receipts, list) or tuple(required_receipts) != REQUIRED_RECEIPTS:
        errors.append("REGISTRY_RECEIPTS_MISMATCH")

    try:
        state = _load(_safe_source(root, "quantumbot_harness/PROJECT_STATE.json"))
        errors.extend(validate_m0_state(state))
    except (OSError, PermissionError, ValueError) as exc:
        errors.append(f"STATE_UNAVAILABLE:{type(exc).__name__}")

    try:
        spec = _load(_safe_source(root, "quantumbot_harness/specs/SPEC-HARNESS-M0-FORMALIZATION-001.json"))
        if not isinstance(spec, dict) or spec.get("status") != "APPROVED" or not spec.get("approved_by") or not spec.get("approved_at"):
            errors.append("SPEC_APPROVAL_INVALID")
        if not isinstance(spec, dict) or spec.get("spec_id") != registry.get("spec_id"):
            errors.append("SPEC_BINDING_MISMATCH")
    except (OSError, PermissionError, ValueError) as exc:
        errors.append(f"SPEC_UNAVAILABLE:{type(exc).__name__}")

    source_results = {}
    bound_sources = registry.get("bound_sources")
    if not isinstance(bound_sources, dict) or set(bound_sources) != REQUIRED_BOUND_SOURCES:
        errors.append("REGISTRY_BOUND_SOURCES_MISMATCH")
        bound_sources = bound_sources if isinstance(bound_sources, dict) else {}
    safe_sources = {}
    for relative, expected in bound_sources.items():
        if relative not in REQUIRED_BOUND_SOURCES or not isinstance(expected, str) or len(expected) != 64:
            errors.append(f"SOURCE_BINDING_INVALID:{relative}")
            continue
        try:
            safe_sources[relative] = _safe_source(root, relative)
        except (OSError, PermissionError) as exc:
            errors.append(f"SOURCE_PATH_INVALID:{relative}:{type(exc).__name__}")
    # Do not read any source until the entire binding set has passed validation.
    if not errors:
        for relative, path in safe_sources.items():
            expected = bound_sources[relative]
            try:
                actual = _hash(path)
            except OSError as exc:
                errors.append(f"SOURCE_UNAVAILABLE:{relative}:{type(exc).__name__}")
                continue
            source_results[relative] = {"expected": expected, "actual": actual, "match": actual == expected}
            if actual != expected:
                errors.append(f"SOURCE_HASH_MISMATCH:{relative}")

    blockers = registry.get("known_blockers")
    if not isinstance(blockers, list) or not blockers:
        errors.append("BLOCKER_REGISTER_MISSING")
    preservation = registry.get("preservation_evidence")
    if not isinstance(preservation, dict):
        errors.append("PRESERVATION_EVIDENCE_INVALID")
        preservation = {}
    if preservation.get("changed_historical_paths") != [] or preservation.get("deleted_artifacts") != []:
        errors.append("HISTORICAL_PRESERVATION_NOT_CLEAN")

    return {
        "registry_id": registry.get("registry_id"),
        "status": "BLOCKED" if errors else EXPECTED_STATUS,
        "formal_gate_status": EXPECTED_FORMAL_GATE_STATUS if not errors else "BLOCKED",
        "certification_effect": "NONE",
        "errors": errors,
        "source_results": source_results,
        "known_blockers": blockers if isinstance(blockers, list) else [],
        "limits": [
            "This verifier checks an additive registry; it does not create or certify a gate.",
            "Absent historical bar/byte measurements remain UNKNOWN and are not converted to zero.",
            "It does not read real FINAL_HOLDOUT, credentials, or trading database contents.",
            "Independent external disposition remains required before any formal M0 gate.",
        ],
    }
